        public static string NameOf(string hash)
        {
            if (hash == null) return null;
            for (int i = 0; i < All.Length; i++)
                if (All[i].Hash == hash) return All[i].Name;
            return null;
        }

        public static Weapon[] Find(string partial)
        {
            if (string.IsNullOrEmpty(partial)) return new Weapon[0];
            string term = partial.ToLowerInvariant();
            var found = new System.Collections.Generic.List<Weapon>();
            for (int i = 0; i < All.Length; i++)
            {
                Weapon w = All[i];
                if ((w.Name != null && w.Name.ToLowerInvariant().Contains(term)) ||
                    (w.Hash != null && w.Hash.ToLowerInvariant().Contains(term)))
                    found.Add(w);
            }
            return found.ToArray();
        }
    }
